INSERT INTO "Patchnote" ("version", "type", "date", "titleEn", "titleFr", "entries") VALUES
('0.8.8', 'patch', '2026-08-06T12:00:00.000Z', 'Smaller, hardened image and a tighter API', 'Image plus légère et durcie, API mieux protégée', '[{"type":"fix","titleEn":"The Seerr-compatible API is now rate limited","titleFr":"L''API compatible Seerr est désormais limitée en débit","descEn":"/api/v1 is public by design so third-party apps can reach it. It now caps requests per minute, so an unauthenticated flood can no longer keep the server busy.","descFr":"L''API /api/v1 est publique par conception, pour que les applications tierces puissent s''y connecter. Elle plafonne désormais le nombre de requêtes par minute : un flot non authentifié ne peut plus occuper le serveur."},{"type":"perf","titleEn":"Lighter, hardened container image","titleFr":"Image conteneur plus légère et durcie","descEn":"The image moved to a hardened base and dropped everything it never loads. Roughly 20% smaller, and no dependency can run an install script during the build unless it is explicitly allowed.","descFr":"L''image passe sur une base durcie et perd tout ce qu''elle ne charge jamais. Environ 20% plus légère, et aucune dépendance ne peut exécuter de script d''installation pendant la construction sans autorisation explicite."},{"type":"fix","titleEn":"Dependencies brought up to date","titleFr":"Dépendances remises à jour","descEn":"Cleared 12 of 14 security findings, including a critical one in the archive library. The two left are documented as not reachable in Oscarr.","descFr":"12 des 14 alertes de sécurité sont résolues, dont une critique dans la bibliothèque d''archives. Les deux restantes sont documentées comme non atteignables dans Oscarr."}]')
ON CONFLICT ("version") DO NOTHING;
